<?php
declare(strict_types=1);
require '/home/uptep/private/app/bootstrap.php';
require '/home/uptep/private/app/view.php';
require '/home/uptep/private/app/web-convoys.php';
require '/home/uptep/private/app/convoy-daily.php';
require '/home/uptep/private/app/convoy-consumption.php';
$u=requireUser();$error='';$member=null;$confirmation=null;$data=[];
$tabs=['tableau'=>'Demandes','nouvelle'=>'Nouvelle demande','livraisons'=>'Livraisons','mes-convois'=>'Mes convois'];
$tab=is_string($_GET['vue']??null)?$_GET['vue']:'tableau';
$success=$_SESSION['convoy_success']??null;unset($_SESSION['convoy_success']);
try {
    $member=convoyIdentity($u);
    if($member['reports'])$tabs+=['demandes'=>'Historique des demandes','convois'=>'Historique des convois','statistiques'=>'Statistiques','recap-demandes'=>'Récapitulatif'];
    if(!isset($tabs[$tab]))throw new DomainException('Cette rubrique n’est pas accessible avec tes droits.',403);
    if($_SERVER['REQUEST_METHOD']==='POST'){
        if(!validCsrf())throw new DomainException('Le formulaire a expiré. Recharge la page.',403);
        if(isset($u['_preview']))throw new DomainException('Le mode visualisation est en lecture seule.',403);
        if(post('action')==='confirmer'){
            $key=post('confirmation');$job=$_SESSION['convoy_pending'][$key]??null;
            if(!$job||$job['expires']<time()||$job['body']['discord_id']!==$member['discord_id'])throw new DomainException('Confirmation expirée. Recommence depuis la demande.',409);
            if($job['action']==='convoi'&&isset($job['overage'])&&($job['overage']['pommes']!=='0'||$job['overage']['materiaux']!=='0')){if(post('overage_confirmed')!=='1')throw new DomainException('Confirme explicitement le dépassement.',422);$job['body']['overage_confirmed']=$job['overage'];}
            if($job['action']==='convoi'&&($job['auto_warning']??false)){if(post('auto_production_confirmed')!=='1')throw new DomainException('Confirme le convoi vers cette demande en auto production.',422);$job['body']['auto_production_confirmed']=true;}
            $out=null;
            try{[$status,$out]=$job['action']==='annulation_convoi'?botCancelConvoy(db(),db(true),$job['id'],$job['body']):botConvoyAction(db(),db(true),$job['action'],$job['id'],$job['body'],'convoyEvent');}
            catch(DomainException $ex){
                if($job['action']!=='convoi'||$ex->getCode()!==409||!preg_match('/dépassement|auto production/i',$ex->getMessage()))throw $ex;
                // A definite rejection made no write: issue a fresh, unconfirmed preview.
                $d=botDemand(db(),$job['id']);$job['overage']=botConvoyOverage($d,$job['body']['nbpomme'],$job['body']['nbmateriaux']);$job['auto_warning']=(bool)$d['auto_production'];
                unset($job['body']['overage_confirmed'],$job['body']['auto_production_confirmed'],$_SESSION['convoy_pending'][$key]);
                $job['body']['commande_id']='web:'.bin2hex(random_bytes(24));$key=bin2hex(random_bytes(20));$_SESSION['convoy_pending'][$key]=$job;$confirmation=['key'=>$key]+$job;
                $error='La demande a changé. Vérifie les avertissements actualisés avant de confirmer.';
            }
            // Keep the immutable command until expiry: a repeated submission replays safely.
            if($out!==null){$_SESSION['convoy_success']='Opération enregistrée. Le tableau Discord sera actualisé automatiquement.';
            redirect('/convois.php'.(isset($out['demande']['id'])?'?id='.$out['demande']['id']:''));}
        }else{
            $job=convoyPrepare($member);$key=bin2hex(random_bytes(20));
            $_SESSION['convoy_pending']=array_filter($_SESSION['convoy_pending']??[],fn($v)=>$v['expires']>=time());
            if(count($_SESSION['convoy_pending'])>=30)array_shift($_SESSION['convoy_pending']);
            $_SESSION['convoy_pending'][$key]=$job;$confirmation=['key'=>$key]+$job;
        }
    }
    $page=is_string($_GET['page']??null)?$_GET['page']:'1';$after=is_string($_GET['apres']??null)?$_GET['apres']:'0';
    if($tab==='tableau'){
        if(isset($_GET['id'])){$id=botNumber($_GET['id'],true);$data=['demandes'=>[botDemand(db(),$id)],'suite_apres'=>null];$cv=botListConvoys(db(),$id,['apres'=>$after]);$data['demandes'][0]['convois']=array_map(fn($c)=>$c+['pseudo_demandeur'=>$data['demandes'][0]['pseudo_demandeur']],$cv['convois']);$data['convoy_next']=$cv['suite_apres'];}
        else $data=botListDemands(db(),['apres'=>$after,'etat'=>is_string($_GET['etat']??null)?$_GET['etat']:'les_deux']);
    }elseif($tab==='livraisons')$data=botDeliveries(db(),db(true),['discord_id'=>$member['discord_id'],'vitesse'=>is_string($_GET['vitesse']??null)?$_GET['vitesse']:'0','page'=>$page]);
    elseif($tab==='mes-convois'){
        // Own history, including cancelled declarations. Never expose another player's history through this tab.
        $cursor=botNumber($after);$q=db()->prepare('SELECT c.*,d.pseudo_demandeur FROM convois_effectues c JOIN demandes_convois d ON d.id=c.iddemande WHERE c.idenvoyeur=? AND c.id>? ORDER BY c.id LIMIT 51');$q->execute([$member['player_id'],$cursor]);$rows=$q->fetchAll(PDO::FETCH_ASSOC);$more=count($rows)>50;$rows=array_slice($rows,0,50);$data=['lignes'=>$rows,'suite_apres'=>$more?(string)end($rows)['id']:null];
    }elseif($tab==='statistiques'){
        $query=['discord_id'=>$member['discord_id']];
        foreach(['ressource','sens','joueur'] as $key)if(isset($_GET[$key]))$query[$key]=$_GET[$key];
        $data=convoyDailyStatistics(db(),db(true),$query,$u);
        // Consumption chart: independent of the 7-day filters; a bad date range only affects this block.
        try{[$consoFrom,$consoEnd]=convoyConsumptionRange($_GET);$data['consumption']=convoyConsumptionData(db(),db(true),$consoFrom,$consoEnd);}
        catch(DomainException $ex){$data['consumption_error']=$ex->getMessage();}
    }elseif($tab!=='nouvelle'){
        $query=['discord_id'=>$member['discord_id'],'page'=>$page];
        if($tab!=='recap-demandes')foreach(['periode','debut','fin','joueur','etat','expediteur','destinataire','demande'] as $key)if(is_string($_GET[$key]??null)&&$_GET[$key]!=='')$query[$key]=$_GET[$key];
        $data=botReports(db(),db(true),$tab,$query,null,!in_array($tab,['statistiques','recap-demandes'],true),$u);
    }
}catch(DomainException $ex){http_response_code($ex->getCode()?:422);$error=$ex->getMessage();}
catch(Throwable $ex){error_log('UPTEP web convoys: '.$ex->getMessage());http_response_code(503);$error='Les convois sont momentanément indisponibles. Réessaie dans quelques instants.';}
