ert"><strong>Cette demande est en auto production.</strong><p>Souhaites-tu quand même déclarer ce convoi ?</p><label class="convoy-checkbox"><input type="checkbox" name="auto_production_confirmed" value="1" required> Oui, je confirme ce convoi.</label></div><?php endif; ?><button class="save-user" type="submit">Confirmer</button> <a href="/convois.php">Abandonner</a></form><?php if($confirmation['action']==='convoi'): ?><details><summary>Modifier les montants</summary><form class="convoy-form" method="post"><?php convoyHidden('convoi',['id'=>$confirmation['id']]); ?><label>Pommes<input name="pommes" required value="<?= e($confirmation['body']['nbpomme']) ?>"></label><label>Matériaux<input name="materiaux" required value="<?= e($confirmation['body']['nbmateriaux']) ?>"></label><label>Durée du trajet<input name="duree" required value="<?= e((string)max(0,strtotime($confirmation['body']['date_arrivee'])-strtotime($confirmation['body']['date_convoi']))) ?>s"></label><button class="save-user">Vérifier les montants modifiés</button></form></details><?php endif; ?></section>
