<?php else: $columns=$tab==='demandes'?['id'=>'Demande','pseudo_demandeur'=>'Joueur','objet'=>'Objet','niveau'=>'Niveau','auto_production'=>'Auto production','nbpomme_original'=>'Pommes demandées','nbmateriaux_original'=>'Matériaux demandés','nbpomme_restant'=>'Pommes restantes','nbmateriaux_restant'=>'Matériaux restants','etat'=>'État','date_demande'=>'Date']:($tab==='recap-demandes'?['pseudo'=>'Joueur','demandes_effectuees'=>'Demandes','demandes_validees'=>'Validées','demandes_terminees'=>'Terminées','demandes_annulees'=>'Annulées','derniere_demande'=>'Dernière demande']:['pseudo'=>'Joueur','envois'=>'Envois','receptions'=>'Réceptions','pommes_envoyees'=>'Pommes envoyées','materiaux_envoyes'=>'Matériaux envoyés','pommes_recues'=>'Pommes reçues','materiaux_recus'=>'Matériaux reçus','moyenne_pommes_envoyees'=>'Pommes envoyées / jour','moyenne_materiaux_envoyes'=>'Matériaux envoyés / jour','moyenne_pommes_recues'=>'Pommes reçues / jour','moyenne_materiaux_recus'=>'Matériaux reçus / jour']); ?>
<div class="users-panel users-scroll"><table class="users-table"><thead><tr><?php foreach($columns as $label): ?><th><?= e($label) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($data['lignes']??[] as $row): ?><tr><?php foreach($columns as $key=>$label): ?><td><?php if($key==='id'): ?><a href="/convois.php?id=<?= e((string)$row[$key]) ?>">#<?= e((string)$row[$key]) ?></a><?php elseif($key==='auto_production'): ?><?= ($row[$key]??false)?'Auto production':'—' ?><?php elseif(in_array($key,['date_demande','derniere_demande'])): ?><?= e(convoyDate($row[$key])) ?><?php else: ?><?= e((string)($row[$key]??'—')) ?><?php endif; ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table><?php if(empty($data['lignes'])): ?><p class="chaine-empty">Aucun résultat pour ces critères.</p><?php endif; ?></div><?php endif; ?>
<?php endif; ?>
<?php if(!in_array($tab,['statistiques','recap-demandes'],true) && isset($data['page'],$data['pages'])): ?><nav class="convoy-pagination" aria-label="Pagination"><span>Page <?= (int)$data['page'] ?> / <?= (int)$data['pages'] ?> · <?= (int)$data['total'] ?> résultats</span><?php if($data['page']>1)convoyLink(['page'=>(string)($data['page']-1)],'Précédente'); ?><?php if($data['page']<$data['pages'])convoyLink(['page'=>(string)($data['page']+1)],'Suivante'); ?></nav><?php endif; ?>
<?php endif;endif; ?></div><script src="/assets/convoy-tables.js?v=1" defer></script><?php workspaceEnd();
function convoyTable(array $rows,array $member): void { ?>
<div class="users-scroll"><table class="users-table"><thead><tr><th>Convoi / demande</th><th>Expéditeur</th><th>Destinataire</th><th>Pommes</th><th>Matériaux</th><th>Départ</th><th>Arrivée</th><th>État</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $c): ?><tr><td>#<?= e((string)$c['id']) ?> · <a href="/convois.php?id=<?= e((string)$c['iddemande']) ?>">demande #<?= e((string)$c['iddemande']) ?></a></td><td><?= e($c['pseudo_envoyeur']) ?></td><td><?= e($c['pseudo_demandeur']??'—') ?></td><td><?= convoyAmount($c['nbpomme']) ?></td><td><?= convoyAmount($c['nbmateriaux']) ?></td><td><?= e(convoyDate($c['date_convoi'])) ?></td><td><?= e(convoyDate($c['date_arrivee'])) ?></td><td><?= $c['annule']?'Annulé':'Déclaré' ?></td><td><?php if(!$c['annule'] && ($member['is_chaine']||(string)$c['idenvoyeur']===$member['player_id'])): ?><form method="post"><?php convoyHidden('annulation_convoi',['id'=>(string)$c['id']]); ?><button class="save-user">Annuler</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table><?php if(!$rows): ?><p class="chaine-empty">Aucun convoi.</p><?php endif; ?></div>
<?php }
